import './index.scss';

const CartTableItem = ({ product }) => {

    return (
        <div className='cart-item' key={product.id}>
            <div className='cart-item__image'></div>
            {product.title} - Quantity: {product.quantity}
        </div>
    )
}

export default CartTableItem
